const body = $json.body ?? $json;
const auth = $json.headers?.authorization;

// 1. Validar campos requeridos
const required = ['clientName', 'rfc', 'documentType', 'fiscalPeriod'];
const missing = required.filter((key) => !body[key] || typeof body[key] !== 'string');
const rfcPattern = /^[A-ZÑ&]{3,4}\d{6}[A-Z0-9]{3}$/i;

if (missing.length || !rfcPattern.test(body.rfc ?? '')) {
  return [{
    json: {
      errorOccurred: true,
      statusCode: 422,
      response: {
        success: false,
        code: 'VALIDATION_ERROR',
        error: `Solicitud inválida: ${missing.join(', ') || 'RFC con formato inválido'}`
      }
    }
  }];
}

return [{
  json: {
    errorOccurred: false,
    clientName: body.clientName,
    rfc: body.rfc,
    documentType: body.documentType,
    fiscalPeriod: body.fiscalPeriod,
    notes: body.notes || '',
    file: body.file || null,
    documentId: body.documentId || `DOC-${Date.now()}`,
    expedienteId: body.expedienteId || null,
    storagePath: body.storagePath || null,
    signedFileUrl: body.signedFileUrl || null
  }
}];

const payload = $('Validar Payload Entrante').first().json;

// Si ocurrió un error en la descarga o no hay URL firmada
if ($json.error || !payload.signedFileUrl) {
  const fileUrlStatus = !payload.signedFileUrl ? 'URL firmada no proporcionada o expirada' : 'No fue posible descargar el archivo de Supabase Storage';
  return [{
    json: {
      errorOccurred: true,
      statusCode: 400,
      response: {
        success: false,
        code: 'FILE_DOWNLOAD_ERROR',
        error: `Error al acceder al documento: ${fileUrlStatus}.`
      }
    }
  }];
}

// Analizar si es un archivo XML CFDI
const fileName = (payload.file?.name || '').toLowerCase();
const fileType = (payload.file?.type || '').toLowerCase();
const isXml = fileName.endsWith('.xml') || fileType.includes('xml');

let xmlContent = null;
if (isXml && $binary && $binary.data) {
  try {
    const buffer = Buffer.from($binary.data.data, 'base64');
    xmlContent = buffer.toString('utf-8');
  } catch (e) {
    xmlContent = null;
  }
}

return [{
  json: {
    ...payload,
    isXml,
    xmlContent,
    hasBinary: !!($binary && $binary.data)
  },
  binary: $binary
}];

const payload = $('Identificar Tipo y Procesar XML/PDF').first().json;

// Si ocurrió un error previo en la tubería
if (payload.errorOccurred) {
  return [{ json: payload }];
}

let aiRaw = '';
try {
  aiRaw = $json.text || $json.output || JSON.stringify($json);
} catch (e) {
  aiRaw = '';
}

// Limpiar posibles bloques Markdown
let cleanJsonStr = aiRaw.trim();
if (cleanJsonStr.startsWith('```')) {
  cleanJsonStr = cleanJsonStr.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
}

let parsedAi = null;
try {
  parsedAi = JSON.parse(cleanJsonStr);
} catch (e) {
  const jsonMatch = cleanJsonStr.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      parsedAi = JSON.parse(jsonMatch[0]);
    } catch (err) {
      parsedAi = null;
    }
  }
}

// 1. Validar si el JSON devuelto por Gemini es válido
if (!parsedAi || typeof parsedAi !== 'object') {
  return [{
    json: {
      errorOccurred: true,
      statusCode: 502,
      response: {
        success: false,
        code: 'INVALID_AI_RESPONSE',
        error: 'El agente de IA no devolvió un análisis en formato JSON válido.'
      }
    }
  }];
}

// 2. Validar tipos de datos numéricos y campos clave
const subtotal = Number(parsedAi.subtotal) || 0;
const tax = Number(parsedAi.tax) || 0;
const total = Number(parsedAi.total) || 0;
const confidence = typeof parsedAi.confidence === 'number' ? parsedAi.confidence : 0.95;
const alerts = Array.isArray(parsedAi.alerts) ? parsedAi.alerts : [];
const rfc = (parsedAi.rfc || payload.rfc || '').toString().trim().toUpperCase();
const issuer = (parsedAi.issuer || payload.clientName || 'Emisor No Identificado').toString().trim();
const date = (parsedAi.date || new Date().toISOString().slice(0, 10)).toString().slice(0, 10);

// Validar consistencia matemática de montos
if (total > 0 && Math.abs((subtotal + tax) - total) > 0.05) {
  alerts.push(`Discrepancia en montos: Subtotal ($${subtotal}) + IVA ($${tax}) != Total ($${total})`);
}

// 3. Formatear respuesta final según el contrato exacto de ContaFácil Pro
return [{
  json: {
    errorOccurred: false,
    statusCode: 200,
    response: {
      success: true,
      documentId: payload.documentId,
      status: 'processed',
      extractedData: {
        rfc: rfc,
        issuer: issuer,
        date: date,
        subtotal: subtotal,
        tax: tax,
        total: total
      },
      alerts: alerts,
      integrationMode: 'n8n'
    }
  }
}];
